import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, mix, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

const CARD_W = 1.5;
const CARD_H = 1.9;
const GAP = 0.25;
const ROW_W = 3 * CARD_W + 2 * GAP;

const CARDS = [
  { glyph: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
  { glyph: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
  { glyph: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' },
];

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'feature-triptych';

  const timelines = [];
  const disposables = [];
  const cardGroups = [];

  const topHex = new THREE.Color('#191921');
  const bottomHex = new THREE.Color('#121218');

  CARDS.forEach((data, i) => {
    const cardGroup = new THREE.Group();
    const x = -ROW_W / 2 + CARD_W / 2 + i * (CARD_W + GAP);
    cardGroup.position.set(x, 0, 0);

    // Card body (rounded via texture-less gradient plane, corner radius approximated with UV alpha)
    const cardGeo = new THREE.PlaneGeometry(CARD_W, CARD_H, 1, 1);
    disposables.push(cardGeo);

    const vUv = uv();
    const gradient = mix(vec3(topHex.r, topHex.g, topHex.b), vec3(bottomHex.r, bottomHex.g, bottomHex.b), vUv.y.oneMinus());

    const cardMat = new THREE.MeshStandardNodeMaterial();
    cardMat.colorNode = vec4(gradient, 1.0);
    cardMat.roughness = 0.6;
    cardMat.metalness = 0.25;
    cardMat.clearcoat = 0.15;
    cardMat.clearcoatRoughness = 0.3;
    disposables.push(cardMat);

    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardMesh.name = `card-${i}`;
    cardGroup.add(cardMesh);

    // hairline border
    const borderGeo = new THREE.PlaneGeometry(CARD_W + 0.012, CARD_H + 0.012, 1, 1);
    disposables.push(borderGeo);
    const borderMat = new THREE.MeshBasicNodeMaterial();
    borderMat.colorNode = vec4(0.149, 0.149, 0.184, 1.0);
    disposables.push(borderMat);
    const borderMesh = new THREE.Mesh(borderGeo, borderMat);
    borderMesh.position.z = -0.001;
    cardGroup.add(borderMesh);

    // icon seat disc
    const discRadius = 0.2;
    const discGeo = new THREE.CylinderGeometry(discRadius, discRadius, 0.05, 32);
    disposables.push(discGeo);
    const discMat = new THREE.MeshStandardNodeMaterial();
    discMat.roughness = 0.55;
    discMat.metalness = 0.5;
    discMat.clearcoat = 0.2;
    discMat.color = new THREE.Color('#2a2a33');
    disposables.push(discMat);
    const discMesh = new THREE.Mesh(discGeo, discMat);
    discMesh.rotation.x = Math.PI / 2;

    const padding = 0.375;
    const topY = CARD_H / 2 - padding;
    discMesh.position.set(0, topY - discRadius, 0.03);
    cardGroup.add(discMesh);

    // glyph text on disc face
    const glyphMesh = createTextMesh({
      text: data.glyph,
      font: 'JetBrains Mono',
      fontWeight: 700,
      fontSize: 0.09,
      color: '#ff2a38',
      emissiveIntensity: 1.6,
      anchor: 'center',
      atlas: ctx.fontAtlas,
    });
    glyphMesh.position.set(0, topY - discRadius, 0.065);
    cardGroup.add(glyphMesh);
    disposables.push(glyphMesh.geometry, glyphMesh.material);

    // title
    const titleY = topY - discRadius * 2 - GAP;
    const titleMesh = createTextMesh({
      text: data.title,
      font: 'Lora',
      fontWeight: 600,
      fontSize: 0.1,
      color: '#e8ecf2',
      anchor: 'top-center',
      maxWidth: CARD_W - padding * 2,
      atlas: ctx.fontAtlas,
    });
    titleMesh.position.set(0, titleY, 0.02);
    cardGroup.add(titleMesh);
    disposables.push(titleMesh.geometry, titleMesh.material);

    // body
    const bodyY = titleY - 0.25 - 0.125;
    const bodyMesh = createTextMesh({
      text: data.body,
      font: 'JetBrains Mono',
      fontWeight: 400,
      fontSize: 0.065,
      color: '#e8ecf2',
      anchor: 'top-center',
      maxWidth: CARD_W - padding * 2,
      lineHeight: 1.5,
      atlas: ctx.fontAtlas,
    });
    bodyMesh.position.set(0, bodyY, 0.02);
    cardGroup.add(bodyMesh);
    disposables.push(bodyMesh.geometry, bodyMesh.material);

    // contact shadow plane
    const shadowGeo = new THREE.PlaneGeometry(CARD_W * 1.05, CARD_H * 0.15, 1, 1);
    disposables.push(shadowGeo);
    const shadowMat = new THREE.MeshBasicNodeMaterial();
    shadowMat.colorNode = vec4(0.0, 0.0, 0.0, 0.35);
    shadowMat.transparent = true;
    disposables.push(shadowMat);
    const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
    shadowMesh.position.set(0, -CARD_H / 2 - 0.05, -0.05);
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.material.opacity = 0.35;
    cardGroup.add(shadowMesh);

    cardGroup.userData = { discMat, shadowMesh, index: i };
    cardGroups.push(cardGroup);
    root.add(cardGroup);
  });

  // stagger-cards + fade-up mount animation
  cardGroups.forEach((cg, i) => {
    cg.position.y += 0.2;
    cg.children.forEach(c => { if (c.material) c.material.transparent = true; });
    const startOpacity = { v: 0 };
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(cg.position, {
      y: cg.position.y - 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.to(startOpacity, {
      v: 1,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
      onUpdate: () => {
        cg.traverse(o => {
          if (o.material && 'opacity' in o.material) o.material.opacity = startOpacity.v;
        });
      },
    }, 0);
    timelines.push(tl);
  });

  // hover lift handlers
  let hoveredIndex = -1;
  const hoverTimelines = new Map();

  function setHover(index, isHover) {
    const cg = cardGroups[index];
    if (!cg) return;
    const existing = hoverTimelines.get(index);
    if (existing) existing.kill();
    const discMat = cg.userData.discMat;
    const tl = gsap.timeline();
    tl.to(cg.position, {
      y: isHover ? 0.06 : 0,
      z: isHover ? 0.12 : 0,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.to(discMat, {
      emissiveIntensity: isHover ? 2.2 : 1.6,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    hoverTimelines.set(index, tl);
    timelines.push(tl);
  }

  root.userData.handlers = {
    onPointerMove: (event) => {
      const point = event.point || event;
      let closest = -1;
      let minDist = Infinity;
      cardGroups.forEach((cg, i) => {
        const dx = point.x - cg.position.x;
        const dz = point.z !== undefined ? point.z - cg.position.z : 0;
        const dist = Math.abs(dx);
        if (dist < CARD_W / 2 && dist < minDist) {
          minDist = dist;
          closest = i;
        }
      });
      if (closest !== hoveredIndex) {
        if (hoveredIndex !== -1) setHover(hoveredIndex, false);
        if (closest !== -1) setHover(closest, true);
        hoveredIndex = closest;
      }
    },
    onPointerLeave: () => {
      if (hoveredIndex !== -1) {
        setHover(hoveredIndex, false);
        hoveredIndex = -1;
      }
    },
  };

  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    hoverTimelines.forEach(tl => tl.kill());
    disposables.forEach(d => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
  };

  return root;
}
